cd /app && cat > app/javascript/controllers/reactions_controller.js <<'EOF'
import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = [ "trigger", "template" ]

  #composer = null

  open() {
    this.#composer = this.templateTarget.content.firstElementChild.cloneNode(true)
    this.triggerTarget.hidden = true
    this.triggerTarget.after(this.#composer)
    this.#composer.querySelector("input").focus()
  }

  close() {
    this.#composer?.remove()
    this.#composer = null
    this.triggerTarget.hidden = false
    this.triggerTarget.focus()
  }

  validate({ target }) {
    this.#updateSubmit(target.form)
  }

  submitStart({ target }) {
    target.querySelector("[type=submit]").disabled = true
  }

  submitEnd({ target, detail: { success } }) {
    if (success) {
      this.close()
    } else {
      this.#updateSubmit(target)
    }
  }

  #updateSubmit(form) {
    form.querySelector("[type=submit]").disabled = form.querySelector("input").value.trim() === ""
  }
}
EOF
